'use strict';
(function(){
const data=window.PoeticsStates,h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cityStates={Damaturu:'Yobe',Jalingo:'Taraba',Lokoja:'Kogi',Aba:'Abia',Umuahia:'Abia',Abakaliki:'Ebonyi',Owerri:'Imo',Orerokpe:'Delta',Yenagoa:'Bayelsa',Asaba:'Delta','Issele-Uku':'Delta','Ikot Ekpene':'Akwa Ibom','Ado Ekiti':'Ekiti',Awka:'Anambra',Sokoto:'Sokoto',Karu:'Nasarawa',Bauchi:'Bauchi','Ile-Ife':'Osun',Ilesa:'Osun',Abeokuta:'Ogun',Lagos:'Lagos',Ibadan:'Oyo',Ogbomoso:'Oyo',Maiduguri:'Borno',Abuja:'Federal Capital Territory',Jos:'Plateau',Kano:'Kano',Enugu:'Enugu',Calabar:'Cross River',Zaria:'Kaduna',Gombe:'Gombe',Ilorin:'Kwara',Kaduna:'Kaduna','Port Harcourt':'Rivers',Uyo:'Akwa Ibom',Makurdi:'Benue','Benin City':'Edo',Yola:'Adamawa',Lafia:'Nasarawa'};
const categories=['People','Places','Platforms','Prizes','Publications'],colors={People:'#0b5f78',Places:'#fde9dc',Platforms:'#e94f27',Prizes:'#eee7dc',Publications:'#171717'};
const frequencyBands=[{min:0,label:'0',fill:'#eee7dc'},{min:1,label:'1–4',fill:'#dcebee'},{min:5,label:'5–14',fill:'#b8d7df'},{min:15,label:'15–29',fill:'#70a8b9'},{min:30,label:'30+',fill:'#0b5f78'}];
function frequencyBand(total){return frequencyBands.filter(b=>total>=b.min).at(-1)||frequencyBands[0];}
function breakdown(value){return typeof value==='number'?{People:value,Places:0,Platforms:0,Prizes:0,Publications:0}:Object.fromEntries(categories.map(c=>[c,Math.max(0,Number(value?.[c])||0)]));}
function render(counts,selected='All states',zoom=1,options={}){
const factor=viewBox(selected)[2]/744/zoom,visible=options.enabledStates?new Set(options.enabledStates):new Set(data.locations.map(s=>s.name));
const labels=[],badges=[];
const shapes=data.locations.map(s=>{
 const point=s.labelPoint||s.center,values=breakdown(counts[s.name]),total=categories.reduce((sum,c)=>sum+values[c],0),shown=visible.has(s.name),parts=categories.filter(c=>values[c]>0),description=parts.map(c=>c+': '+values[c]).join(', '),band=frequencyBand(total),classes=`nigeria-state ${s.name===selected?'selected':''} ${total&&shown?'has-records':''} ${total>=30?'frequency-high':''} ${shown?'':'hidden-state'}`;
 labels.push(`<g class="${classes}" aria-hidden="true"><text class="state-name" x="${point[0]}" y="${point[1]+(total&&shown&&!options.nationalCollapsed?(parts.length>2?28:19)*factor:0)}" style="font-size:${8*factor}px" text-anchor="middle">${h(s.id==='fct'?'FCT':s.name)}</text></g>`);
 if(total&&shown)badges.push(`<g class="state-entry-count" data-state-count="${h(s.name)}" data-count="${total}" transform="translate(${point[0]},${point[1]})" aria-hidden="${options.compactStateCounts?'false':'true'}">${s.name!==selected&&!(options.expandedCounts||[]).includes(s.name)&&options.compactStateCounts?`<g data-expand-state-count="${h(s.name)}" tabindex="0" role="button" aria-label="${h(s.name)}: ${total} entries. Select to zoom and show categories." style="pointer-events:all;cursor:pointer"><circle r="${12*factor}" fill="#67617d" stroke="#fffaf3" stroke-width="${factor}"/><text y="${3*factor}" fill="#fffaf3" style="font-size:${9*factor}px" text-anchor="middle">${total}</text></g>`:parts.map((category,i)=>{
 const count=values[category],x=parts.length===5?(i<3?(i-1)*19:(i===3?-9.5:9.5))*factor:parts.length===1||parts.length===3&&i===2?0:(i%2?10:-10)*factor,y=parts.length>2?(i<(parts.length===5?3:2)?-10:10)*factor:0;
 const ink=['People','Publications'].includes(category)?'#fffaf3':'#171717';
 return `<g data-category-count="${category}" data-count="${count}" data-category-state="${h(s.name)}" tabindex="0" role="button" aria-label="${h(s.name)}: ${count} ${category} entries" style="pointer-events:all;cursor:pointer" transform="translate(${x},${y})"><circle r="${8.5*factor}" style="fill:${colors[category]}"/><text y="${3*factor}" style="fill:${ink};font-size:${(count>99?7:8.5)*factor}px" text-anchor="middle">${count}</text></g>`;
 }).join('')}</g>`);
 return `<g class="${classes}" style="--state-fill:${band.fill};--state-border:${total>=30?'#fffaf3':'#315766'}" data-frequency-band="${band.label}" ${shown?`data-map-state="${h(s.name)}" tabindex="0"`:'tabindex="-1" aria-disabled="true"'} role="button" aria-label="${h(s.name)}: ${shown?total:0} directory entries${shown&&description?'; '+h(description):''}"><title>${h(s.name)} · ${shown?total:0} matching entries${shown&&description?' · '+h(description):''}${shown?' · select to zoom':' · hidden in legend'}</title><path d="${s.path}"/></g>`;
}).join('');
const national=false&&options.nationalCollapsed&&selected==='All states'?`<g data-national-count="true" role="button" tabindex="0" aria-label="Nigeria: ${Number(options.nationalCount)||0} matching entries. Double-click, tap on a phone, or press Enter to expand state counts." style="cursor:pointer"><title>Nigeria · ${Number(options.nationalCount)||0} matching entries · double-click to expand states</title><circle cx="370" cy="270" r="34" fill="#0b5f78" stroke="#fffaf3" stroke-width="2"/><text x="370" y="269" fill="#fffaf3" text-anchor="middle" style="font-size:18px;font-weight:700">${Number(options.nationalCount)||0}</text><text x="370" y="286" fill="#fffaf3" text-anchor="middle" style="font-size:9px">Nigeria</text></g>`:'';
return `<svg class="nigeria-gis nigeria-state-map${options.showBoundaries===false?' boundaries-hidden':''}" viewBox="0 0 744 600" role="group" aria-label="Nigeria: 36 states and the Federal Capital Territory. Select a state to zoom and browse poetry records."><g class="state-shapes">${shapes}</g><g class="state-labels" pointer-events="none" aria-hidden="true">${labels.join('')}</g><g class="state-count-overlay" pointer-events="none" aria-hidden="${options.compactStateCounts?'false':'true'}">${badges.join('')}</g>${national}</svg>`;
}
function viewBox(name){const state=data.locations.find(s=>s.name===name);if(!state)return [0,0,744,600];const [x0,y0,x1,y1]=state.bounds,cx=(x0+x1)/2,cy=(y0+y1)/2;let w=Math.max(75,(x1-x0)*1.18),height=Math.max(65,(y1-y0)*1.18);if(w/height>744/600)height=w*600/744;else w=height*744/600;return [cx-w/2,cy-height/2,w,height];}
function statesForRecord(r){const cities=String(r.city||'').split(/\s*\/\s*|;\s*/);return [...new Set(cities.map(c=>cityStates[c]||(data.locations.some(s=>s.name===c)?c:null)).filter(Boolean))];}
window.PoeticsStateMap={render,viewBox,cityStates,statesForRecord,states:data.locations,metadata:data.metadata,categories,colors,breakdown,frequencyBands,frequencyBand};
})();
